{
  "steps": [
    {
      "id": 1,
      "claim": "The regulation classifies individuals by having a drug arrest/conviction or being in current drug‑abuse treatment.",
      "evidence": "Problem statement explicitly bars \"persons with a drug arrest and conviction and/or those undergoing current treatment for drug abuse\" from working in certain state‑run facilities.",
      "weight": 0.10,
      "depends_on": []
    },
    {
      "id": 2,
      "claim": "Drug‑related status is not a suspect or quasi‑suspect class for Equal Protection purposes.",
      "evidence": "Supreme Court precedent (e.g., Washington v. Davis, 426 U.S. 229 (1976); City of Cleburne v. Cleburne Living Center, Inc., 527 U.S. 267 (1999)) holds that classifications based on drug use or addiction are non‑suspect and receive only rational‑basis review.",
      "weight": 0.35,
      "depends_on": [1]
    },
    {
      "id": 3,
      "claim": "The right to a specific state‑run job is not a fundamental right protected by the Due Process Clause.",
      "evidence": "The Supreme Court has recognized a general liberty interest in employment, but not a fundamental right to a particular public position; restrictions for safety reasons are permissible without strict scrutiny.",
      "weight": 0.25,
      "depends_on": [1]
    },
    {
      "id": 4,
      "claim": "Because neither a suspect class nor a fundamental right is implicated, the regulation is reviewed under the rational‑basis test.",
      "evidence": "Equal Protection doctrine: non‑suspect classifications and non‑fundamental rights are subject to rational‑basis review, requiring only a legitimate governmental interest and a rational relation to that interest.",
      "weight": 0.20,
      "depends_on": [2, 3]
    },
    {
      "id": 5,
      "claim": "Protecting public safety in state‑run facilities is a legitimate state interest, and the regulation is rationally related to that interest.",
      "evidence": "The problem states the prohibition is \"necessary to protect the public from potential problems,\" and public safety is a recognized legitimate governmental interest.",
      "weight": 0.10,
      "depends_on": [4]
    }
  ],
  "answer": "D",
  "confidence": 0.99,
  "considered": [
    {
      "answer": "A",
      "reason_rejected": "Strict scrutiny applies only to suspect classes or fundamental rights; drug‑user status is not a suspect class."
    },
    {
      "answer": "B",
      "reason_rejected": "Intermediate scrutiny applies only to quasi‑suspect classes such as gender; drug‑user status is not quasi‑suspect."
    },
    {
      "answer": "C",
      "reason_rejected": "Although it names the rational‑basis test, its rationale ('discrimination is generally favored') misstates the legal standard."
    }
  ]
}
